v = currentValue.value
if v is None or not currentValue.quality.isGood():
	return
base = str(tagPath).rsplit('/', 2)[0]
p = [base + '/Val/Val_PVMaxCapt', base + '/Val/Val_PVMinCapt']
mx, mn = [q.value for q in system.tag.readBlocking(p)]
w, x = [], []
if mx is None or v > mx:
	w.append(p[0]); x.append(v)
if mn is None or v < mn:
	w.append(p[1]); x.append(v)
if w:
	system.tag.writeBlocking(w, x)
